import { FormEvent, useEffect, useState } from "react";
import { api, ApiError, keys, Sample } from "./api";
import { goTo } from "./App";
import { rememberNewLink } from "./Report";

export default function Describe() {
  const [description, setDescription] = useState("");
  const [priceList, setPriceList] = useState("");
  const [photo, setPhoto] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<ApiError | null>(null);
  const [samples, setSamples] = useState<Sample[]>([]);
  const existing = keys.mine(); // businesses whose owner link was opened in this browser

  useEffect(() => {
    api.samples().then(setSamples).catch(() => setSamples([]));
  }, []);

  async function submit(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    setError(null);
    try {
      const b = await api.create(description, priceList, photo);
      if (b.owner_key) keys.setOwner(b.id, b.owner_key, b.profile.name);
      if (b.owner_link) rememberNewLink(b.id, b.owner_link);
      goTo(`#/b/${b.id}/saved`);
    } catch (err) {
      setError(err instanceof ApiError ? err : new ApiError(String(err), 0));
    } finally {
      setBusy(false);
    }
  }

  return (
    <>
      <h1>Describe your business</h1>
      <p className="tagline">
        Tell us in your own words what you sell, where, and when you're open. Paste your price list or add a photo of
        it. We'll turn it into your website — you can check and change everything next.
      </p>

      {samples.length > 0 && (
        <p className="samples">
          Try an example:{" "}
          {samples.map((s) => (
            <button
              key={s.id}
              type="button"
              className="chip"
              onClick={() => {
                setDescription(s.description);
                setPriceList(s.price_list);
              }}
            >
              {s.owner_name}, {s.city}
            </button>
          ))}
        </p>
      )}

      <form className="card" onSubmit={submit}>
        <label className="field">
          <span>About your business</span>
          <textarea
            rows={6}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Hi, I'm Meera. I bake eggless cakes at home in Baner, Pune…"
            maxLength={4000}
          />
        </label>
        <label className="field">
          <span>Price list</span>
          <textarea
            rows={6}
            value={priceList}
            onChange={(e) => setPriceList(e.target.value)}
            placeholder={"Chocolate cake 1/2 kg - ₹650\nCupcakes box of 6 - ₹420"}
            maxLength={4000}
          />
        </label>
        <label className="field">
          <span>Or a photo of your menu / price list (optional)</span>
          <input type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => setPhoto(e.target.files?.[0] ?? null)} />
        </label>
        {error && <ErrorBox error={error} />}
        <button className="btn btn-primary" type="submit" disabled={busy || (!description.trim() && !priceList.trim() && !photo)}>
          {busy ? "Reading your business…" : "Make my website"}
        </button>
      </form>

      {existing.length > 0 && (
        <section className="existing">
          <h2>Your businesses on this device</h2>
          <ul>
            {existing.map((b) => (
              <li key={b.id}>
                <a href={`#/b/${b.id}`}>{b.name}</a>
                <a className="muted" href={`#/b/${b.id}/report`}>
                  launch report
                </a>
              </li>
            ))}
          </ul>
        </section>
      )}
    </>
  );
}

export function ErrorBox({ error }: { error: ApiError }) {
  return (
    <div className="status status-error" role="alert">
      <p>{error.message}</p>
      {error.details !== null && typeof error.details !== "string" && (
        <details>
          <summary>Details</summary>
          <pre>{JSON.stringify(error.details, null, 2)}</pre>
        </details>
      )}
    </div>
  );
}
import { useEffect, useState } from "react";
import { api, ApiError, Business, NameIdea, Plan, Step, usd } from "./api";
import { goTo } from "./App";
import { ErrorBox } from "./Describe";

/** Step 3: choose where the site goes — free address now, or the seller's own name. */
export function LaunchChoice({ businessId }: { businessId: number }) {
  const [biz, setBiz] = useState<Business | null>(null);
  const [names, setNames] = useState<NameIdea[] | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<ApiError | null>(null);

  useEffect(() => {
    api.get(businessId).then(setBiz).catch(setError);
  }, [businessId]);

  const run = async (label: string, fn: () => Promise<void>) => {
    setBusy(label);
    setError(null);
    try {
      await fn();
    } catch (e) {
      setError(e instanceof ApiError ? e : new ApiError(String(e), 0));
    } finally {
      setBusy(null);
    }
  };

  const makePlan = (mode: "sandbox" | "full", domain?: string) =>
    run(mode, async () => {
      const p = await api.createPlan(businessId, mode, domain);
      goTo(`#/b/${businessId}/plan/${p.id}`);
    });

  if (!biz) return error ? <ErrorBox error={error} /> : <p>Loading…</p>;
  const freeHost = biz.site_url ? new URL(biz.site_url).host : "";

  return (
    <>
      <h1>Put {biz.profile.name} online</h1>
      <p className="tagline">Pick where your website lives. You'll see every step and the total cost before anything happens.</p>

      <section className="card choice">
        <h2>Free address</h2>
        <p>
          <strong>{freeHost}</strong> — ready in a few minutes, costs nothing. You can move to your own name later.
        </p>
        <button className="btn btn-primary" disabled={!!busy} onClick={() => makePlan("sandbox")}>
          {busy === "sandbox" ? "Preparing…" : "Use the free address"}
        </button>
      </section>

      <section className="card choice">
        <h2>Your own name</h2>
        <p>Like meerascakes.in. We suggest names that are really available, with their price.</p>
        {names === null ? (
          <button
            className="btn btn-ghost"
            disabled={!!busy}
            onClick={() => run("names", async () => setNames(await api.names(businessId)))}
          >
            {busy === "names" ? "Finding names…" : "Suggest names"}
          </button>
        ) : names.length === 0 ? (
          <p className="muted">We couldn't find a free name right now. Try again later, or use the free address.</p>
        ) : (
          <ul className="names">
            {names.map((n) => (
              <li key={n.domain}>
                <span>
                  <strong>{n.domain}</strong> <span className="muted">{usd(n.price_usd)} for the first year</span>
                </span>
                <button className="btn btn-ghost btn-sm" disabled={!!busy} onClick={() => makePlan("full", n.domain)}>
                  {busy === "full" ? "Preparing…" : "Choose"}
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      {error && <ErrorBox error={error} />}
      <p>
        <a href={`#/b/${businessId}`}>← Back to your details</a>
      </p>
    </>
  );
}

const STATUS_ICON: Record<Step["status"], string> = {
  pending: "○",
  running: "◌",
  done: "✅",
  skipped: "➖",
  failed: "⚠️",
  blocked: "⛔",
};

/** Step 4–5: the approval card (draft) and then the live step log (polled). */
export function PlanView({ businessId, planId }: { businessId: number; planId: number }) {
  const [plan, setPlan] = useState<Plan | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [name, setName] = useState("");
  const [agreed, setAgreed] = useState(false);
  const [busy, setBusy] = useState(false);

  const load = () => api.plan(businessId, planId).then(setPlan).catch(setError);
  useEffect(() => {
    load();
  }, [planId]);

  const active = plan && (plan.status === "approved" || plan.status === "running");
  const [watched, setWatched] = useState(false);
  useEffect(() => {
    if (!active) return;
    setWatched(true);
    const t = window.setInterval(load, 1000);
    return () => window.clearInterval(t);
  }, [active]);
  // When a launch we were watching finishes, go straight to the proof.
  useEffect(() => {
    if (watched && plan?.status === "done") {
      const t = window.setTimeout(() => goTo(`#/b/${businessId}/report`), 1200);
      return () => window.clearTimeout(t);
    }
  }, [watched, plan?.status]);

  if (!plan) return error ? <ErrorBox error={error} /> : <p>Loading…</p>;

  const act = async (fn: () => Promise<unknown>) => {
    setBusy(true);
    setError(null);
    try {
      await fn();
      await load();
    } catch (e) {
      setError(e instanceof ApiError ? e : new ApiError(String(e), 0));
    } finally {
      setBusy(false);
    }
  };

  const costLine =
    plan.total_cost_usd > 0
      ? `${usd(plan.total_cost_usd)} for ${plan.zone} (first year)`
      : plan.mode === "sandbox"
        ? "Free"
        : `Nothing to buy — you already own ${plan.zone}`;

  if (plan.status === "draft") {
    return (
      <>
        <h1>Check and approve</h1>
        <p className="tagline">Nothing is bought or changed until you tap Approve.</p>
        <section className="card approval">
          <dl className="summary">
            <div>
              <dt>Your website</dt>
              <dd>{plan.site_host}</dd>
            </div>
            <div>
              <dt>Total cost</dt>
              <dd className="cost">{costLine}</dd>
            </div>
            {plan.email_plan_estimate_usd !== null && (
              <div>
                <dt>Email plan, bought separately on GoDaddy</dt>
                <dd>
                  about {usd(plan.email_plan_estimate_usd)} a year{" "}
                  <span className="muted">(estimate — not part of the total; you pay GoDaddy for it yourself)</span>
                </dd>
              </div>
            )}
            <div>
              <dt>Orders are emailed to</dt>
              <dd>{plan.mailbox}</dd>
            </div>
          </dl>

          <h2>What we'll do</h2>
          <ol className="todo">
            {plan.steps.map((s) => (
              <li key={s.id}>{s.title}</li>
            ))}
          </ol>

          <h2>Settings we'll change</h2>
          <ul className="settings">
            {plan.changes.map((c) => (
              <li key={`${c.type}-${c.name}`}>
                {c.say}
                <details>
                  <summary>Details</summary>
                  <table className="diff">
                    <tbody>
                      <tr>
                        <th>Record</th>
                        <td>
                          {c.type} {c.name === "@" ? c.zone : `${c.name}.${c.zone}`}
                        </td>
                      </tr>
                      <tr>
                        <th>Before</th>
                        <td>{c.before_text.length ? c.before_text.join("\n") : "(none)"}</td>
                      </tr>
                      <tr>
                        <th>After</th>
                        <td className="after">{c.after_text.join("\n")}</td>
                      </tr>
                    </tbody>
                  </table>
                </details>
              </li>
            ))}
          </ul>
          <details>
            <summary>Technical details of each step</summary>
            <ul className="tech">
              {plan.steps.map((s) => (
                <li key={s.id}>
                  <strong>{s.title}:</strong> {s.detail}
                </li>
              ))}
            </ul>
          </details>

          <label className="field">
            <span>Your name</span>
            <input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Meera Iyer" maxLength={80} />
          </label>
          <label className="agree">
            <input type="checkbox" checked={agreed} onChange={(e) => setAgreed(e.target.checked)} /> I agree to these
            changes{plan.total_cost_usd > 0 ? ` and the cost of ${usd(plan.total_cost_usd)}` : ""}.
          </label>
          {error && <ErrorBox error={error} />}
          <div className="actions">
            <button
              className="btn btn-primary"
              disabled={busy || !agreed || !name.trim()}
              onClick={() => act(() => api.approve(businessId, plan.id, name.trim()))}
            >
              {busy ? "Starting…" : "Approve and launch"}
            </button>
            <a className="btn btn-ghost" href={`#/b/${plan.business_id}/launch`}>
              Go back
            </a>
          </div>
        </section>
      </>
    );
  }

  const stopped = plan.status === "failed" || plan.status === "blocked";
  const waitingToBuy =
    plan.practice && plan.status === "blocked" && plan.steps.some((s) => s.kind === "get_domain" && s.status === "blocked");
  return (
    <>
      <h1>
        {plan.status === "done" ? "Your website is on!" : stopped ? "Launch paused" : "Launching your website…"}
      </h1>
      <p className="tagline">{plan.site_host}</p>
      <ol className="card steplog" aria-live="polite">
        {plan.steps.map((s) => (
          <li key={s.id} className={`st-${s.status}`}>
            <span className="icon" aria-hidden>
              {STATUS_ICON[s.status]}
            </span>
            <div>
              <div className="title">{s.title}</div>
              {s.message && <div className="msg">{s.message}</div>}
              <details>
                <summary>Details</summary>
                <p>{s.detail}</p>
                {s.started_at && <p className="muted">Started {new Date(s.started_at).toLocaleTimeString()}</p>}
              </details>
            </div>
          </li>
        ))}
      </ol>
      {waitingToBuy && (
        <p className="practice" role="note">
          Practice mode: nothing is really bought. Tap “Pretend I bought it” to carry on as if you had bought{" "}
          {plan.zone} on godaddy.com.
        </p>
      )}
      {error && <ErrorBox error={error} />}
      <div className="actions">
        {waitingToBuy && (
          <button className="btn btn-primary" disabled={busy} onClick={() => act(() => api.practiceBuy(businessId, plan.id))}>
            {busy ? "Continuing…" : "Pretend I bought it (practice)"}
          </button>
        )}
        {stopped && !waitingToBuy && (
          <button
            className="btn btn-primary"
            disabled={busy}
            onClick={() => act(() => api.resume(businessId, plan.id))}
          >
            {busy ? "Resuming…" : "Resume"}
          </button>
        )}
        {plan.status === "done" && (
          <a className="btn btn-primary" href={`#/b/${businessId}/report`}>
            See your launch report →
          </a>
        )}
        {plan.status === "done" && plan.site_url && (
          <a className="btn btn-ghost" href={plan.site_url} target="_blank" rel="noreferrer">
            Open my website
          </a>
        )}
        <a className="btn btn-ghost" href={`#/b/${plan.business_id}`}>
          Back to your details
        </a>
      </div>
    </>
  );
}

content.content:
:root {
  --bg: #fbfaf7;
  --fg: #1d1d1b;
  --muted: #5c5b57;
  --ok-bg: #e7f5ec;
  --ok-fg: #1d6b3a;
  --err-bg: #fdecea;
  --err-fg: #9b2c1f;
  --card: #ffffff;
  --border: #e4e1da;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--fg);
  background: var(--bg);
}

body {
  margin: 0;
  background: var(--bg);
}

.page {
  max-width: 40rem;
  margin: 0 auto;
  padding: 3rem 1rem;
}

h1 {
  margin: 0 0 0.5rem;
  font-size: 2rem;
}

.tagline {
  color: var(--muted);
  font-size: 1.1rem;
  line-height: 1.5;
}

.status {
  margin-top: 2rem;
  padding: 1rem 1.25rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--card);
  font-size: 1.1rem;
}

.status-ok {
  background: var(--ok-bg);
  color: var(--ok-fg);
}

.status-error {
  background: var(--err-bg);
  color: var(--err-fg);
}

details {
  margin-top: 0.75rem;
  font-size: 0.9rem;
  color: var(--muted);
}

pre {
  white-space: pre-wrap;
  margin: 0.5rem 0 0;
}

/* ---- M2: describe + review screens ---- */
:root { --brand: #9a3412; --brand-soft: #fdecdf; }
* { box-sizing: border-box; }
.top { margin-bottom: 1.5rem; }
.logo { font-weight: 700; color: var(--fg); text-decoration: none; letter-spacing: -0.01em; }
h2 { font-size: 1.25rem; margin: 2rem 0 0.5rem; }
.muted { color: var(--muted); }
.card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 1rem 1.25rem; }
.field { display: grid; gap: 0.35rem; margin: 0 0 1rem; }
.field > span { font-weight: 600; }
.field small { color: var(--muted); }
input, textarea { font: inherit; padding: 0.6rem 0.75rem; border: 1px solid #d3cfc6; border-radius: 10px;
  background: #fff; color: var(--fg); width: 100%; }
input[type="file"] { border: 0; padding: 0; }
input:focus, textarea:focus, button:focus-visible, a:focus-visible { outline: 3px solid #f6ad7b; outline-offset: 1px; }
.btn { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 0.6rem 1.2rem;
  border-radius: 999px; border: 0; font: inherit; font-weight: 600; cursor: pointer; text-decoration: none; }
.btn:disabled { opacity: 0.6; cursor: default; }
.btn-primary { background: var(--brand); color: #fff; }
.btn-ghost { background: var(--brand-soft); color: var(--brand); }
.chip { font: inherit; font-size: 0.9rem; margin: 0.25rem 0.35rem 0 0; padding: 0.35rem 0.8rem; border-radius: 999px;
  border: 1px solid var(--border); background: var(--card); cursor: pointer; }
.samples { color: var(--muted); }
.existing ul, .orders { list-style: none; padding: 0; margin: 0; }
.existing li { display: flex; gap: 0.75rem; padding: 0.4rem 0; }
.products .product { display: grid; gap: 0 0.75rem; grid-template-columns: 1fr 7rem; padding: 0.75rem 0;
  border-bottom: 1px solid var(--border); }
.products .product .grow { grid-column: 1 / -1; }
.products .remove { justify-self: start; min-height: 36px; padding: 0.3rem 0.9rem; font-size: 0.9rem; }
.products > .btn { margin-top: 0.75rem; }
.address { display: flex; align-items: center; gap: 0.4rem; }
.address input { max-width: 16rem; }
.actions { display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem; margin: 1.5rem 0; }
.saved { color: var(--ok-fg); font-weight: 600; }
.orders li { padding: 0.6rem 0; border-bottom: 1px solid var(--border); }
.orders li:last-child { border-bottom: 0; }
.warn { color: var(--err-fg); }
.status p { margin: 0; }
.health { margin-top: 3rem; font-size: 0.9rem; color: var(--muted); }
.health-ok { color: var(--ok-fg); }
.health-error { color: var(--err-fg); }
@media (min-width: 640px) {
  .products .product { grid-template-columns: 2fr 7rem 1fr; }
  .products .product .grow:first-child { grid-column: auto; }
