/* LaunchWitness design tokens — the single source for colour, type, space, shape and motion.
   Components only use these variables; change the look here. */
:root {
  /* colour */
  --cream: #f5efe4;
  --cream-2: #efe5d4;
  --cream-glow: #f9d9bf; /* warm peach glow in the background gradient */
  --paper: #fffdf8; /* cards on cream */
  --ink: #161614; /* near-black: dark sections, the frame, primary text */
  --ink-2: #222220; /* raised surfaces on dark */
  --ink-line: #3a3a36; /* outlines on dark */
  --on-ink: #f3eee4; /* text on dark */
  --on-ink-muted: #a7a297;
  --text: #1b1b19;
  --muted: #6b665c;
  --line: #e2d9c8; /* hairlines on cream */
  --line-strong: #cfc4af;

  --accent: #dcf06a; /* soft lime: the ONE accent */
  --accent-ink: #1d2205;
  --accent-soft: #f1f8c6;

  --success: #1f8a4c;
  --success-soft: #e3f3e8;
  --warning: #b7790c;
  --warning-soft: #fbf0d7;
  --danger: #c0402b;
  --danger-soft: #fbe7e2;

  --bg-gradient: radial-gradient(120% 80% at 85% 0%, var(--cream-glow) 0%, rgba(249, 217, 191, 0) 55%),
    radial-gradient(90% 70% at 0% 100%, #f2e8c9 0%, rgba(242, 232, 201, 0) 60%),
    linear-gradient(180deg, var(--cream) 0%, var(--cream-2) 100%);

  /* type */
  --font: "Inter Tight", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, monospace;
  --fs-xs: 0.78rem;
  --fs-sm: 0.88rem;
  --fs-base: 1rem;
  --fs-md: 1.125rem;
  --fs-lg: clamp(1.3rem, 1.1rem + 0.8vw, 1.6rem);
  --fs-xl: clamp(1.8rem, 1.3rem + 2vw, 2.6rem);
  --fs-2xl: clamp(2.2rem, 1.4rem + 3.4vw, 3.6rem);
  --fs-display: clamp(2.7rem, 1.2rem + 6.2vw, 6rem);
  --fw-light: 300;
  --fw-regular: 400;
  --fw-medium: 500;
  --fw-semi: 600;
  --lh-tight: 1.04;
  --lh-snug: 1.25;
  --lh-body: 1.55;
  --tracking-tight: -0.035em;

  /* space (4px base) */
  --s-1: 0.25rem;
  --s-2: 0.5rem;
  --s-3: 0.75rem;
  --s-4: 1rem;
  --s-5: 1.5rem;
  --s-6: 2rem;
  --s-7: 3rem;
  --s-8: 4.5rem;
  --s-9: 7rem;
  --gutter: clamp(16px, 4vw, 48px);
  --frame: clamp(8px, 1.2vw, 16px); /* dark frame thickness */

  /* shape */
  --r-sm: 10px;
  --r-md: 16px;
  --r-lg: 24px;
  --r-xl: clamp(24px, 3vw, 40px);
  --r-pill: 999px;

  /* shadow */
  --shadow-sm: 0 1px 2px rgba(40, 30, 10, 0.06), 0 1px 1px rgba(40, 30, 10, 0.04);
  --shadow-md: 0 10px 30px -12px rgba(40, 30, 10, 0.18), 0 2px 6px rgba(40, 30, 10, 0.05);
  --shadow-lg: 0 40px 80px -30px rgba(20, 15, 5, 0.35);

  /* motion: calm, eased, never bouncy */
  --ease: cubic-bezier(0.22, 1, 0.36, 1); /* ease-out-quint-ish */
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --t-fast: 160ms;
  --t-med: 320ms;
  --t-slow: 600ms;
}

