const { chromium, devices } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const out = process.argv[2];
  for (const [name, ctxOpts] of [['m', { ...devices['iPhone 13'], deviceScaleFactor: 1 }], ['d', { viewport: { width: 1440, height: 900 } }]]) {
    const ctx = await b.newContext(ctxOpts);
    const p = await ctx.newPage();
    p.on('console', m => m.type()==='error' && console.log(name, 'console:', m.text()));
    await p.goto('http://localhost:8000/', { waitUntil: 'networkidle' });
    await p.waitForTimeout(1500);
    const H = await p.evaluate(() => document.documentElement.scrollHeight);
    const W = await p.evaluate(() => [document.documentElement.scrollWidth, innerWidth]);
    console.log(name, 'height', H, 'width', W, 'font', await p.evaluate(() => document.fonts.check('300 40px "Inter Tight"')));
    const vh = ctxOpts.viewport.height;
    for (const f of [0, 0.4, 0.8, 1.2, 2, 3, 4, 5]) {
      const y = Math.round(f * vh);
      if (y > H) break;
      await p.evaluate(y => window.scrollTo(0, y), y);
      await p.waitForTimeout(900);
      await p.screenshot({ path: `${out}/land-${name}-${f}.png` });
    }
    await ctx.close();
  }
  await b.close();
})();
