216 seller.html
<style>
  :root {
    --bg: #fffaf5; --card: #ffffff; --ink: #1f2937; --muted: #6b7280; --line: #eadfd3;
    --brand: #9a3412; --brand-ink: #ffffff; --brand-soft: #fdecdf; --wa: #128c4a; --radius: 14px;
  }
  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body { margin: 0; background: var(--bg); color: var(--ink);
    font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", sans-serif; }
  a { color: var(--brand); }
  .wrap { max-width: 760px; margin: 0 auto; padding: 0 16px; }
  header.bar { position: sticky; top: 0; z-index: 5; background: rgba(255,250,245,.94);
    backdrop-filter: blur(6px); border-bottom: 1px solid var(--line); }
  header.bar .wrap { display: flex; align-items: center; justify-content: space-between; height: 56px; gap: 12px; }
  .brand { font-weight: 700; color: var(--ink); text-decoration: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px;
    padding: 10px 18px; border-radius: 999px; border: 0; font: inherit; font-weight: 600;
    text-decoration: none; cursor: pointer; }
  .btn-primary { background: var(--brand); color: var(--brand-ink); }
  .btn-wa { background: var(--wa); color: #fff; }
  .btn-ghost { background: var(--brand-soft); color: var(--brand); }
  .btn-sm { min-height: 36px; padding: 6px 14px; font-size: 14px; }
  .hero { padding: 36px 0 28px; }
  .hero h1 { font-size: clamp(28px, 7vw, 42px); line-height: 1.15; margin: 0 0 10px; letter-spacing: -.01em; }
  .hero .tagline { font-size: 18px; color: var(--muted); margin: 0 0 6px; }
  .hero .area { font-size: 15px; color: var(--muted); margin: 0 0 20px; }
  .cta { display: flex; flex-wrap: wrap; gap: 10px; }
  section { padding: 22px 0; border-top: 1px solid var(--line); }
  h2 { font-size: 22px; margin: 0 0 14px; }
  h3.cat { font-size: 13px; text-transform: uppercase; letter-spacing: .08em; color: var(--brand);
    margin: 22px 0 8px; }
  h3.cat:first-of-type { margin-top: 4px; }
  .menu { list-style: none; margin: 0; padding: 0; background: var(--card); border: 1px solid var(--line);
    border-radius: var(--radius); }
  .menu li { display: flex; justify-content: space-between; gap: 16px; padding: 14px 16px; }
  .menu li + li { border-top: 1px solid var(--line); }
  .menu .name { font-weight: 600; }
  .menu .desc { font-size: 14px; color: var(--muted); }
  .menu .price { font-weight: 700; white-space: nowrap; }
  .card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; }
  .facts { display: grid; gap: 12px; }
  .facts dt { font-size: 13px; color: var(--muted); }
  .facts dd { margin: 0; font-weight: 600; }
  .pay { display: grid; gap: 16px; align-items: center; }
  .pay svg { width: 180px; height: 180px; background: #fff; border-radius: 10px; }
  .upi-id { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; background: var(--brand-soft);
    padding: 2px 8px; border-radius: 6px; word-break: break-all; }
  form .row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 0; }
  form .row + .row { border-top: 1px solid var(--line); }
  form .row label { flex: 1; }
  form .row small { display: block; color: var(--muted); }
  input[type=number] { width: 72px; }
  input, textarea { font: inherit; padding: 10px 12px; border: 1px solid #d6c8b9; border-radius: 10px;
    background: #fff; color: var(--ink); }
  input:focus, textarea:focus, .btn:focus-visible { outline: 3px solid #f6ad7b; outline-offset: 1px; }
  .field { display: grid; gap: 6px; margin-top: 14px; }
  .field label { font-weight: 600; font-size: 15px; }
  .field input, .field textarea { width: 100%; }
  .hint { font-size: 14px; color: var(--muted); }
  .error { background: #fef2f2; color: #991b1b; border: 1px solid #fecaca; padding: 10px 12px; border-radius: 10px; }
  .ok { background: #f0fdf4; border: 1px solid #bbf7d0; }
  .hp { position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden; }
  footer { padding: 28px 0 40px; color: var(--muted); font-size: 14px; border-top: 1px solid var(--line); }
  footer .wrap { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; }
  .prose p { margin: 0 0 12px; }
  @media (min-width: 640px) {
    .facts { grid-template-columns: 1fr 1fr; }
    .pay { grid-template-columns: 180px 1fr; }
  }
</style>

